[metadata] {"type": "create", "filePath": "/app/output/index.html", "content": "<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>WellSource — Expert health guidance you can trust</title>
  <link rel="preconnect" href="https://fonts.googleapis.com">
  <link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
  <link href="https://fonts.googleapis.com/css2?family=DM+Sans:ital,opsz,wght@0,9..40,300;0,9..40,400;0,9..40,500;0,9..40,600;0,9..40,700;1,9..40,400&display=swap" rel="stylesheet">
  <script src="https://unpkg.com/lucide@latest/dist/umd/lucide.min.js"></script>
  <style>
    *, *::before, *::after { margin: 0; padding: 0; box-sizing: border-box; }

    :root {
      --primary: #02838D;
      --primary-dark: #026a73;
      --primary-light: #e6f5f6;
      --primary-lightest: #f0fafa;
      --dark: #231F20;
      --dark-muted: #4a4546;
      --text: #333333;
      --text-muted: #6b6566;
      --text-light: #8a8485;
      --white: #ffffff;
      --off-white: #fafbfc;
      --gray-50: #f8f9fa;
      --gray-100: #f1f3f5;
      --gray-200: #e9ecef;
      --gray-300: #dee2e6;
      --coral: #e87461;
      --coral-dark: #d4614f;
      --coral-light: #fef0ee;
      --amber: #f0a830;
      --amber-light: #fdf6e8;
      --teal-gradient: linear-gradient(135deg, #02838D 0%, #02a0ad 100%);
      --shadow-sm: 0 1px 3px rgba(0,0,0,0.06), 0 1px 2px rgba(0,0,0,0.04);
      --shadow-md: 0 4px 12px rgba(0,0,0,0.07), 0 2px 4px rgba(0,0,0,0.04);
      --shadow-lg: 0 12px 32px rgba(0,0,0,0.08), 0 4px 8px rgba(0,0,0,0.04);
      --shadow-xl: 0 20px 48px rgba(0,0,0,0.1);
      --radius-sm: 8px;
      --radius-md: 12px;
      --radius-lg: 16px;
      --radius-xl: 20px;
      --font: 'DM Sans', system-ui, -apple-system, sans-serif;
      --max-width: 1280px;
      --transition: 200ms ease;
    }

    html { scroll-behavior: smooth; }

    body {
      font-family: var(--font);
      color: var(--text);
      background: var(--white);
      line-height: 1.6;
      -webkit-font-smoothing: antialiased;
      overflow-x: hidden;
    }

    a { color: inherit; text-decoration: none; }
    button { font-family: inherit; cursor: pointer; border: none; background: none; }
    img { max-width: 100%; display: block; }
    ul { list-style: none; }

    .container { max-width: var(--max-width); margin: 0 auto; padding: 0 24px; }

    /* ========== HEADER ========== */
    .header {
      position: sticky;
      top: 0;
      z-index: 1000;
      background: var(--white);
      border-bottom: 1px solid var(--gray-200);
    }

    .header-top {
      display: flex;
      align-items: center;
      justify-content: space-between;
      padding: 16px 0;
    }

    .logo {
      display: flex;
      align-items: center;
      gap: 8px;
      font-size: 1.5rem;
      font-weight: 700;
      color: var(--primary);
      letter-spacing: -0.02em;
    }

    .logo-icon {
      width: 36px;
      height: 36px;
      background: var(--teal-gradient);
      border-radius: 10px;
      display: flex;
      align-items: center;
      justify-content: center;
      color: white;
    }

    .logo span { color: var(--dark); }

    .header-actions {
      display: flex;
      align-items: center;
      gap: 16px;
    }

    .header-actions a {
      font-size: 0.875rem;
      font-weight: 500;
      color: var(--text-muted);
      transition: color var(--transition);
    }

    .header-actions a:hover { color: var(--primary); }

    .btn-subscribe {
      padding: 8px 20px;
      background: var(--primary);
      color: var(--white) !important;
      border-radius: 100px;
      font-weight: 600;
      font-size: 0.875rem;
      transition: all var(--transition);
    }

    .btn-subscribe:hover {
      background: var(--primary-dark);
      transform: translateY(-1px);
      box-shadow: var(--shadow-md);
    }

    .mobile-menu-btn {
      display: none;
      padding: 8px;
      color: var(--dark);
    }

    /* Main Nav */
    .main-nav {
      display: flex;
      align-items: center;
      gap: 0;
      border-top: 1px solid var(--gray-200);
    }

    .nav-item {
      position: relative;
    }

    .nav-item > button {
      display: flex;
      align-items: center;
      gap: 6px;
      padding: 14px 20px;
      font-size: 0.9375rem;
      font-weight: 500;
      color: var(--dark-muted);
      transition: all var(--transition);
      border-bottom: 2px solid transparent;
    }

    .nav-item > button:hover,
    .nav-item.active > button {
      color: var(--primary);
      background: var(--primary-lightest);
    }

    .nav-item.active > button {
      border-bottom-color: var(--primary);
    }

    .nav-item > button .chevron {
      width: 14px;
      height: 14px;
      transition: transform var(--transition);
    }

    .nav-item.active > button .chevron {
      transform: rotate(180deg);
    }

    /* Mega Menu */
    .mega-menu {
      position: absolute;
      top: 100%;
      left: 0;
      min-width: 580px;
      background: var(--white);
      border: 1px solid var(--gray-200);
      border-top: 2px solid var(--primary);
      border-radius: 0 0 var(--radius-md) var(--radius-md);
      box-shadow: var(--shadow-lg);
      padding: 24px;
      display: none;
      z-index: 100;
      animation: menuFadeIn 200ms ease-out;
    }

    .nav-item.active .mega-menu { display: block; }

    @keyframes menuFadeIn {
      from { opacity: 0; transform: translateY(-8px); }
      to { opacity: 1; transform: translateY(0); }
    }

    .mega-menu-title {
      font-size: 0.75rem;
      font-weight: 600;
      text-transform: uppercase;
      letter-spacing: 0.08em;
      color: var(--primary);
      margin-bottom: 12px;
      padding-bottom: 8px;
      border-bottom: 1px solid var(--gray-100);
    }

    .mega-menu-grid {
      display: grid;
      grid-template-columns: repeat(2, 1fr);
      gap: 4px;
    }

    .mega-menu-grid a {
      display: block;
      padding: 8px 12px;
      font-size: 0.875rem;
      color: var(--text);
      border-radius: var(--radius-sm);
      transition: all var(--transition);
    }

    .mega-menu-grid a:hover {
      background: var(--primary-lightest);
      color: var(--primary);
      padding-left: 16px;
    }

    .mega-menu-cols {
      display: grid;
      grid-template-columns: 1fr 1fr;
      gap: 24px;
    }

    .mega-menu-section-title {
      font-size: 0.7rem;
      font-weight: 700;
      text-transform: uppercase;
      letter-spacing: 0.1em;
      color: var(--text-light);
      margin-bottom: 8px;
      margin-top: 16px;
    }

    .mega-menu-section-title:first-child { margin-top: 0; }

    /* ========== CREDIBILITY TICKER ========== */
    .ticker-bar {
      background: var(--dark);
      color: var(--white);
      overflow: hidden;
      position: relative;
      height: 44px;
    }

    .ticker-track {
      display: flex;
      align-items: center;
      height: 100%;
      animation: ticker 20s linear infinite;
      width: max-content;
    }

    .ticker-track:hover { animation-play-state: paused; }

    .ticker-item {
      display: flex;
      align-items: center;
      gap: 8px;
      padding: 0 40px;
      font-size: 0.8125rem;
      font-weight: 500;
      white-space: nowrap;
      letter-spacing: 0.01em;
    }

    .ticker-item i { color: var(--coral); width: 16px; height: 16px; }
    .ticker-dot {
      width: 4px;
      height: 4px;
      background: rgba(255,255,255,0.3);
      border-radius: 50%;
      flex-shrink: 0;
    }

    @keyframes ticker {
      0% { transform: translateX(0); }
      100% { transform: translateX(-50%); }
    }

    /* ========== HERO ========== */
    .hero {
      padding: 40px 0;
    }

    .hero-grid {
      display: grid;
      grid-template-columns: 1fr 380px;
      gap: 32px;
      align-items: start;
    }

    .hero-main {
      position: relative;
      border-radius: var(--radius-lg);
      overflow: hidden;
      background: linear-gradient(135deg, #024950 0%, #02838D 50%, #41b3a2 100%);
      min-height: 420px;
      display: flex;
      flex-direction: column;
      justify-content: flex-end;
      padding: 40px;
      cursor: pointer;
      transition: box-shadow var(--transition);
    }

    .hero-main:hover { box-shadow: var(--shadow-xl); }

    .hero-badge {
      position: absolute;
      top: 24px;
      left: 24px;
      background: rgba(255,255,255,0.15);
      backdrop-filter: blur(12px);
      border: 1px solid rgba(255,255,255,0.2);
      padding: 8px 16px;
      border-radius: 100px;
      color: var(--white);
      font-size: 0.8125rem;
      font-weight: 600;
      display: flex;
      align-items: center;
      gap: 8px;
    }

    .hero-badge-dot {
      width: 8px;
      height: 8px;
      background: var(--coral);
      border-radius: 50%;
      animation: pulse 2s ease-in-out infinite;
    }

    @keyframes pulse {
      0%, 100% { opacity: 1; }
      50% { opacity: 0.4; }
    }

    .hero-category {
      display: inline-block;
      background: var(--coral);
      color: var(--white);
      padding: 4px 14px;
      border-radius: 100px;
      font-size: 0.75rem;
      font-weight: 600;
      text-transform: uppercase;
      letter-spacing: 0.06em;
      margin-bottom: 16px;
    }

    .hero-title {
      font-size: 2rem;
      font-weight: 700;
      color: var(--white);
      line-height: 1.25;
      margin-bottom: 12px;
      letter-spacing: -0.02em;
    }

    .hero-subtitle {
      font-size: 1rem;
      color: rgba(255,255,255,0.85);
      line-height: 1.5;
      max-width: 520px;
    }

    .hero-pattern {
      position: absolute;
      top: 0;
      right: 0;
      width: 300px;
      height: 300px;
      opacity: 0.1;
      background: radial-gradient(circle at 70% 30%, white 0%, transparent 60%);
    }

    /* Trending sidebar */
    .trending-sidebar {
      background: var(--gray-50);
      border-radius: var(--radius-lg);
      padding: 28px;
      border: 1px solid var(--gray-200);
    }

    .trending-header {
      display: flex;
      align-items: center;
      gap: 8px;
      margin-bottom: 20px;
      padding-bottom: 16px;
      border-bottom: 2px solid var(--primary);
    }

    .trending-header h2 {
      font-size: 1.125rem;
      font-weight: 700;
      color: var(--dark);
    }

    .trending-header i { color: var(--coral); }

    .trending-item {
      padding: 16px 0;
      border-bottom: 1px solid var(--gray-200);
      transition: all var(--transition);
      cursor: pointer;
    }

    .trending-item:last-child { border-bottom: none; padding-bottom: 0; }
    .trending-item:first-child { padding-top: 0; }

    .trending-item:hover { padding-left: 8px; }

    .trending-item-category {
      font-size: 0.6875rem;
      font-weight: 700;
      text-transform: uppercase;
      letter-spacing: 0.08em;
      color: var(--primary);
      margin-bottom: 4px;
    }

    .trending-item-title {
      font-size: 0.9375rem;
      font-weight: 600;
      color: var(--dark);
      line-height: 1.4;
      transition: color var(--transition);
    }

    .trending-item:hover .trending-item-title { color: var(--primary); }

    /* ========== NEWSLETTER CTA ========== */
    .newsletter-cta {
      background: linear-gradient(135deg, #e87461 0%, #f09080 60%, #f0a830 100%);
      padding: 56px 0;
      position: relative;
      overflow: hidden;
    }

    .newsletter-cta::before {
      content: '';
      position: absolute;
      top: -50%;
      right: -10%;
      width: 400px;
      height: 400px;
      background: rgba(255,255,255,0.08);
      border-radius: 50%;
    }

    .newsletter-cta::after {
      content: '';
      position: absolute;
      bottom: -30%;
      left: -5%;
      width: 300px;
      height: 300px;
      background: rgba(255,255,255,0.06);
      border-radius: 50%;
    }

    .newsletter-inner {
      display: flex;
      align-items: center;
      justify-content: space-between;
      gap: 40px;
      position: relative;
      z-index: 1;
    }

    .newsletter-text { flex: 1; }

    .newsletter-label {
      display: inline-flex;
      align-items: center;
      gap: 6px;
      background: rgba(255,255,255,0.2);
      backdrop-filter: blur(8px);
      padding: 6px 14px;
      border-radius: 100px;
      font-size: 0.75rem;
      font-weight: 600;
      color: var(--white);
      margin-bottom: 16px;
    }

    .newsletter-cta h2 {
      font-size: 1.75rem;
      font-weight: 700;
      color: var(--white);
      margin-bottom: 8px;
      letter-spacing: -0.02em;
    }

    .newsletter-cta p {
      font-size: 1rem;
      color: rgba(255,255,255,0.9);
      max-width: 440px;
    }

    .newsletter-form {
      display: flex;
      gap: 12px;
      flex-shrink: 0;
    }

    .newsletter-form input {
      padding: 14px 20px;
      border: 2px solid rgba(255,255,255,0.3);
      background: rgba(255,255,255,0.15);
      backdrop-filter: blur(8px);
      border-radius: var(--radius-md);
      font-size: 0.9375rem;
      color: var(--white);
      width: 300px;
      font-family: var(--font);
      transition: all var(--transition);
    }

    .newsletter-form input::placeholder { color: rgba(255,255,255,0.6); }
    .newsletter-form input:focus {
      outline: none;
      border-color: var(--white);
      background: rgba(255,255,255,0.25);
    }

    .newsletter-form button {
      padding: 14px 32px;
      background: var(--white);
      color: var(--coral);
      border-radius: var(--radius-md);
      font-weight: 700;
      font-size: 0.9375rem;
      transition: all var(--transition);
      white-space: nowrap;
    }

    .newsletter-form button:hover {
      transform: translateY(-2px);
      box-shadow: var(--shadow-lg);
    }

    .newsletter-privacy {
      font-size: 0.75rem;
      color: rgba(255,255,255,0.7);
      margin-top: 8px;
      display: flex;
      align-items: center;
      gap: 4px;
    }

    /* ========== HEALTH TOPICS CAROUSEL ========== */
    .health-topics {
      padding: 64px 0;
    }

    .section-header {
      display: flex;
      align-items: center;
      justify-content: space-between;
      margin-bottom: 32px;
    }

    .section-title {
      font-size: 1.5rem;
      font-weight: 700;
      color: var(--dark);
      letter-spacing: -0.02em;
    }

    .section-header-right {
      display: flex;
      align-items: center;
      gap: 12px;
    }

    .view-all {
      font-size: 0.875rem;
      font-weight: 600;
      color: var(--primary);
      display: flex;
      align-items: center;
      gap: 4px;
      transition: all var(--transition);
    }

    .view-all:hover { gap: 8px; }

    .carousel-nav {
      display: flex;
      gap: 8px;
    }

    .carousel-btn {
      width: 40px;
      height: 40px;
      display: flex;
      align-items: center;
      justify-content: center;
      border: 2px solid var(--gray-300);
      border-radius: 50%;
      color: var(--dark-muted);
      transition: all var(--transition);
    }

    .carousel-btn:hover {
      border-color: var(--primary);
      color: var(--primary);
      background: var(--primary-lightest);
    }

    .carousel-btn:disabled {
      opacity: 0.3;
      cursor: not-allowed;
    }

    .carousel-btn:disabled:hover {
      border-color: var(--gray-300);
      color: var(--dark-muted);
      background: none;
    }

    .topics-carousel {
      display: flex;
      gap: 24px;
      overflow-x: auto;
      scroll-behavior: smooth;
      padding-bottom: 8px;
      -ms-overflow-style: none;
      scrollbar-width: none;
    }

    .topics-carousel::-webkit-scrollbar { display: none; }

    .topic-card {
      flex: 0 0 auto;
      width: 160px;
      text-align: center;
      cursor: pointer;
      transition: all var(--transition);
    }

    .topic-card:hover { transform: translateY(-4px); }

    .topic-image {
      width: 128px;
      height: 128px;
      border-radius: 50%;
      margin: 0 auto 14px;
      overflow: hidden;
      border: 3px solid var(--gray-200);
      transition: border-color var(--transition);
      background: var(--primary-light);
      display: flex;
      align-items: center;
      justify-content: center;
    }

    .topic-card:hover .topic-image { border-color: var(--primary); }

    .topic-image img {
      width: 100%;
      height: 100%;
      object-fit: cover;
    }

    .topic-image i { color: var(--primary); }

    .topic-card h3 {
      font-size: 0.875rem;
      font-weight: 600;
      color: var(--dark);
    }

    /* ========== TOOLS SECTION ========== */
    .tools-section {
      padding: 64px 0;
      background: var(--gray-50);
    }

    .tools-grid {
      display: grid;
      grid-template-columns: 1fr 1fr;
      gap: 32px;
    }

    .tool-block {
      background: var(--white);
      border-radius: var(--radius-lg);
      padding: 32px;
      border: 1px solid var(--gray-200);
      transition: box-shadow var(--transition);
    }

    .tool-block:hover { box-shadow: var(--shadow-md); }

    .tool-block-header {
      margin-bottom: 20px;
    }

    .tool-block-tag {
      display: inline-flex;
      align-items: center;
      gap: 6px;
      font-size: 0.6875rem;
      font-weight: 700;
      text-transform: uppercase;
      letter-spacing: 0.08em;
      color: var(--primary);
      background: var(--primary-light);
      padding: 4px 12px;
      border-radius: 100px;
      margin-bottom: 12px;
    }

    .tool-block h3 {
      font-size: 1.25rem;
      font-weight: 700;
      color: var(--dark);
      margin-bottom: 8px;
    }

    .tool-block p {
      font-size: 0.875rem;
      color: var(--text-muted);
      line-height: 1.6;
      margin-bottom: 20px;
    }

    .tool-block-cta {
      display: inline-flex;
      align-items: center;
      gap: 6px;
      font-size: 0.875rem;
      font-weight: 600;
      color: var(--primary);
      padding: 8px 0;
      transition: all var(--transition);
      margin-bottom: 20px;
    }

    .tool-block-cta:hover { gap: 10px; }

    .tool-list {
      display: flex;
      flex-direction: column;
      gap: 12px;
    }

    .tool-card {
      display: flex;
      align-items: flex-start;
      gap: 14px;
      padding: 16px;
      background: var(--gray-50);
      border-radius: var(--radius-md);
      transition: all var(--transition);
      cursor: pointer;
    }

    .tool-card:hover {
      background: var(--primary-lightest);
      transform: translateX(4px);
    }

    .tool-card-icon {
      width: 40px;
      height: 40px;
      flex-shrink: 0;
      border-radius: var(--radius-sm);
      display: flex;
      align-items: center;
      justify-content: center;
      color: var(--white);
    }

    .tool-card-icon.teal { background: var(--teal-gradient); }
    .tool-card-icon.coral { background: linear-gradient(135deg, #e87461, #f09080); }
    .tool-card-icon.amber { background: linear-gradient(135deg, #f0a830, #f5c058); }

    .tool-card h4 {
      font-size: 0.875rem;
      font-weight: 600;
      color: var(--dark);
      margin-bottom: 2px;
    }

    .tool-card p {
      font-size: 0.8125rem;
      color: var(--text-muted);
      margin-bottom: 0;
      line-height: 1.5;
    }

    /* ========== RECOMMENDED READS ========== */
    .recommended-reads {
      padding: 64px 0;
    }

    .tabs {
      display: flex;
      gap: 4px;
      margin-bottom: 32px;
      flex-wrap: wrap;
      border-bottom: 2px solid var(--gray-200);
      padding-bottom: 0;
    }

    .tab-btn {
      padding: 12px 20px;
      font-size: 0.875rem;
      font-weight: 500;
      color: var(--text-muted);
      border-bottom: 2px solid transparent;
      margin-bottom: -2px;
      transition: all var(--transition);
      background: none;
    }

    .tab-btn:hover { color: var(--primary); }

    .tab-btn.active {
      color: var(--primary);
      font-weight: 600;
      border-bottom-color: var(--primary);
    }

    .reads-grid {
      display: grid;
      grid-template-columns: repeat(3, 1fr);
      gap: 24px;
    }

    .article-card {
      background: var(--white);
      border-radius: var(--radius-md);
      overflow: hidden;
      border: 1px solid var(--gray-200);
      transition: all 300ms ease;
      cursor: pointer;
    }

    .article-card:hover {
      transform: translateY(-4px);
      box-shadow: var(--shadow-lg);
      border-color: transparent;
    }

    .article-card-img {
      height: 180px;
      background: var(--primary-light);
      display: flex;
      align-items: center;
      justify-content: center;
      position: relative;
      overflow: hidden;
    }

    .article-card-img img {
      width: 100%;
      height: 100%;
      object-fit: cover;
      transition: transform 500ms ease;
    }

    .article-card:hover .article-card-img img {
      transform: scale(1.05);
    }

    .article-card-img i { color: var(--primary); opacity: 0.4; }

    .article-card-body { padding: 20px; }

    .article-card-category {
      font-size: 0.6875rem;
      font-weight: 700;
      text-transform: uppercase;
      letter-spacing: 0.08em;
      color: var(--primary);
      margin-bottom: 8px;
    }

    .article-card h3 {
      font-size: 1rem;
      font-weight: 600;
      color: var(--dark);
      line-height: 1.4;
      margin-bottom: 8px;
      transition: color var(--transition);
