    .article-card-meta span {
      display: flex;
      align-items: center;
      gap: 4px;
    }

    /* ========== TRUST PILLARS ========== */
    .trust-section {
      padding: 80px 0;
      background: var(--primary-lightest);
      position: relative;
    }

    .trust-section::before {
      content: '';
      position: absolute;
      top: 0;
      left: 0;
      right: 0;
      height: 4px;
      background: var(--teal-gradient);
    }

    .trust-intro {
      text-align: center;
      max-width: 600px;
      margin: 0 auto 48px;
    }

    .trust-intro .section-title {
      font-size: 1.75rem;
      margin-bottom: 12px;
    }

    .trust-intro p {
      color: var(--text-muted);
      font-size: 1rem;
    }

    .trust-grid {
      display: grid;
      grid-template-columns: repeat(4, 1fr);
      gap: 24px;
    }

    .trust-card {
      background: var(--white);
      border-radius: var(--radius-lg);
      padding: 32px 24px;
      text-align: center;
      border: 1px solid var(--gray-200);
      transition: all 300ms ease;
    }

    .trust-card:hover {
      transform: translateY(-4px);
      box-shadow: var(--shadow-lg);
      border-color: var(--primary);
    }

    .trust-card-icon {
      width: 56px;
      height: 56px;
      border-radius: 16px;
      display: flex;
      align-items: center;
      justify-content: center;
      margin: 0 auto 20px;
      color: var(--white);
    }

    .trust-card-icon.teal { background: var(--teal-gradient); }
    .trust-card-icon.coral { background: linear-gradient(135deg, #e87461, #f09080); }
    .trust-card-icon.amber { background: linear-gradient(135deg, #f0a830, #f5c058); }
    .trust-card-icon.green { background: linear-gradient(135deg, #2ecc71, #27ae60); }

    .trust-card h3 {
      font-size: 1rem;
      font-weight: 700;
      color: var(--dark);
      margin-bottom: 8px;
    }

    .trust-card p {
      font-size: 0.8125rem;
      color: var(--text-muted);
      line-height: 1.6;
    }

    /* ========== FEATURED PROGRAMS ========== */
    .featured-programs {
      padding: 64px 0;
    }

    .programs-grid {
      display: grid;
      grid-template-columns: repeat(4, 1fr);
      gap: 24px;
    }

    .program-card {
      border-radius: var(--radius-md);
      overflow: hidden;
      position: relative;
      cursor: pointer;
      transition: all 300ms ease;
      border: 1px solid var(--gray-200);
    }

    .program-card:hover {
      transform: translateY(-4px);
      box-shadow: var(--shadow-lg);
    }

    .program-card-img {
      height: 180px;
      display: flex;
      align-items: center;
      justify-content: center;
    }

    .program-card-img.skin { background: linear-gradient(135deg, #fce4ec, #f8bbd0); }
    .program-card-img.ms { background: linear-gradient(135deg, #e3f2fd, #bbdefb); }
    .program-card-img.eczema { background: linear-gradient(135deg, #e8f5e9, #c8e6c9); }
    .program-card-img.mens { background: linear-gradient(135deg, #e0f7fa, #b2ebf2); }

    .program-card-img i { opacity: 0.3; }

    .program-card-body {
      padding: 16px 20px;
      background: var(--white);
    }

    .program-card h3 {
      font-size: 0.9375rem;
      font-weight: 600;
      color: var(--dark);
      line-height: 1.4;
      transition: color var(--transition);
    }

    .program-card:hover h3 { color: var(--primary); }

    /* ========== LATEST VIDEOS ========== */
    .latest-videos {
      padding: 64px 0;
      background: var(--gray-50);
    }

    .videos-grid {
      display: grid;
      grid-template-columns: repeat(4, 1fr);
      gap: 24px;
    }

    .video-card {
      border-radius: var(--radius-md);
      overflow: hidden;
      cursor: pointer;
      transition: all 300ms ease;
      background: var(--white);
      border: 1px solid var(--gray-200);
    }

    .video-card:hover {
      transform: translateY(-4px);
      box-shadow: var(--shadow-lg);
    }

    .video-card-img {
      height: 160px;
      position: relative;
      display: flex;
      align-items: center;
      justify-content: center;
    }

    .video-card-img.v1 { background: linear-gradient(135deg, #a8e6cf, #88d8b0); }
    .video-card-img.v2 { background: linear-gradient(135deg, #ffd3b6, #ffaaa5); }
    .video-card-img.v3 { background: linear-gradient(135deg, #c1c8e4, #8f99ca); }
    .video-card-img.v4 { background: linear-gradient(135deg, #a8d8ea, #7fc8db); }

    .play-btn {
      width: 52px;
      height: 52px;
      background: rgba(255,255,255,0.95);
      border-radius: 50%;
      display: flex;
      align-items: center;
      justify-content: center;
      color: var(--primary);
      transition: all var(--transition);
      box-shadow: var(--shadow-md);
    }

    .video-card:hover .play-btn {
      transform: scale(1.1);
      background: var(--white);
    }

    .video-card-body { padding: 16px 20px; }

    .video-card h3 {
      font-size: 0.875rem;
      font-weight: 600;
      color: var(--dark);
      line-height: 1.4;
      transition: color var(--transition);
    }

    .video-card:hover h3 { color: var(--primary); }

    .video-duration {
      position: absolute;
      bottom: 8px;
      right: 8px;
      background: rgba(0,0,0,0.7);
      color: white;
      padding: 2px 8px;
      border-radius: 4px;
      font-size: 0.6875rem;
      font-weight: 600;
    }

    /* ========== FOOTER ========== */
    .footer {
      background: var(--dark);
      color: var(--white);
      padding: 56px 0 0;
    }

    .footer-top {
      display: grid;
      grid-template-columns: 1fr 1fr;
      gap: 48px;
      padding-bottom: 40px;
      border-bottom: 1px solid rgba(255,255,255,0.1);
