      font-weight: 600;
      font-size: 0.875rem;
      transition: all var(--transition);
      white-space: nowrap;
    }

    .footer-form button:hover { background: var(--primary-dark); }

    .footer-social {
      display: flex;
      align-items: flex-start;
      flex-direction: column;
      justify-content: center;
    }

    .footer-social h3 {
      font-size: 1.25rem;
      font-weight: 700;
      margin-bottom: 16px;
    }

    .social-links {
      display: flex;
      gap: 12px;
    }

    .social-link {
      width: 42px;
      height: 42px;
      border: 1px solid rgba(255,255,255,0.2);
      border-radius: 50%;
      display: flex;
      align-items: center;
      justify-content: center;
      color: rgba(255,255,255,0.7);
      transition: all var(--transition);
    }

    .social-link:hover {
      background: var(--primary);
      border-color: var(--primary);
      color: var(--white);
    }

    .footer-links {
      display: flex;
      flex-wrap: wrap;
      gap: 8px 24px;
      padding: 28px 0;
      border-bottom: 1px solid rgba(255,255,255,0.1);
    }

    .footer-links a {
      font-size: 0.8125rem;
      color: rgba(255,255,255,0.6);
      transition: color var(--transition);
    }

    .footer-links a:hover { color: var(--primary); }

    .footer-legal {
      padding: 24px 0;
      font-size: 0.75rem;
      color: rgba(255,255,255,0.4);
      line-height: 1.6;
    }

    /* ========== MOBILE RESPONSIVE ========== */
    @media (max-width: 1024px) {
      .hero-grid { grid-template-columns: 1fr; }
      .trending-sidebar { display: grid; grid-template-columns: 1fr 1fr; gap: 0; }
      .trending-header { grid-column: 1 / -1; }
      .tools-grid { grid-template-columns: 1fr; }
      .trust-grid { grid-template-columns: repeat(2, 1fr); }
      .programs-grid { grid-template-columns: repeat(2, 1fr); }
      .videos-grid { grid-template-columns: repeat(2, 1fr); }
      .reads-grid { grid-template-columns: repeat(2, 1fr); }
    }

    @media (max-width: 768px) {
      .container { padding: 0 16px; }

      .header-actions .sign-in { display: none; }

      .mobile-menu-btn { display: block; }

      .main-nav {
        display: none;
        flex-direction: column;
        position: absolute;
        top: 100%;
        left: 0;
        right: 0;
        background: var(--white);
        border-bottom: 1px solid var(--gray-200);
        box-shadow: var(--shadow-lg);
      }

      .main-nav.open { display: flex; }

      .nav-item > button {
        width: 100%;
        justify-content: space-between;
      }

      .mega-menu {
        position: static;
        min-width: auto;
        border: none;
        border-top: 1px solid var(--gray-100);
        border-radius: 0;
        box-shadow: none;
        padding: 16px 20px;
      }

      .mega-menu-grid { grid-template-columns: 1fr; }
      .mega-menu-cols { grid-template-columns: 1fr; }

      .hero-main { min-height: 320px; padding: 28px; }
      .hero-title { font-size: 1.5rem; }

      .newsletter-inner { flex-direction: column; text-align: center; }
      .newsletter-form { flex-direction: column; width: 100%; max-width: 400px; margin: 0 auto; }
      .newsletter-form input { width: 100%; }
      .newsletter-cta p { max-width: 100%; }
      .newsletter-privacy { justify-content: center; }

      .trust-grid { grid-template-columns: 1fr; }
      .programs-grid { grid-template-columns: 1fr; }
      .videos-grid { grid-template-columns: 1fr; }
      .reads-grid { grid-template-columns: 1fr; }

      .footer-top { grid-template-columns: 1fr; gap: 32px; }

      .section-title { font-size: 1.25rem; }

      .trending-sidebar { grid-template-columns: 1fr; }
    }

    /* ========== ANIMATIONS ========== */
    .fade-in {
      opacity: 0;
      transform: translateY(20px);
      transition: opacity 600ms ease-out, transform 600ms ease-out;
    }

    .fade-in.visible {
      opacity: 1;
      transform: translateY(0);
    }

    .stagger-1 { transition-delay: 100ms; }
    .stagger-2 { transition-delay: 200ms; }
    .stagger-3 { transition-delay: 300ms; }
    .stagger-4 { transition-delay: 400ms; }
  </style>
