  <script>
    // Mega-menu toggle
    function toggleMenu(btn) {
      const navItem = btn.parentElement;
      const wasActive = navItem.classList.contains('active');

      document.querySelectorAll('.nav-item.active').forEach(item => {
        item.classList.remove('active');
        item.querySelector('button').setAttribute('aria-expanded', 'false');
      });

      if (!wasActive) {
        navItem.classList.add('active');
        btn.setAttribute('aria-expanded', 'true');
      }
    }

    document.addEventListener('click', (e) => {
      if (!e.target.closest('.nav-item')) {
        document.querySelectorAll('.nav-item.active').forEach(item => {
          item.classList.remove('active');
          item.querySelector('button').setAttribute('aria-expanded', 'false');
        });
      }
    });

    // Carousel
    function scrollCarousel(direction) {
      const carousel = document.getElementById('topicsCarousel');
      const scrollAmount = 200;
      carousel.scrollBy({ left: scrollAmount * direction, behavior: 'smooth' });
    }

    // Recommended Reads Tabs
    function switchTab(event, category) {
      document.querySelectorAll('.tab-btn').forEach(btn => {
        btn.classList.remove('active');
        btn.setAttribute('aria-selected', 'false');
      });
      event.target.classList.add('active');
      event.target.setAttribute('aria-selected', 'true');

      const cards = document.querySelectorAll('.article-card');
      cards.forEach((card, index) => {
        const categories = card.dataset.category.split(' ');
        const show = category === 'all' || categories.includes(category);

        card.style.transition = 'opacity 200ms ease, transform 200ms ease';
        if (show) {
          card.style.display = '';
          requestAnimationFrame(() => {
            card.style.opacity = '1';
            card.style.transform = 'translateY(0)';
          });
        } else {
          card.style.opacity = '0';
          card.style.transform = 'translateY(10px)';
          setTimeout(() => { card.style.display = 'none'; }, 200);
        }
      });
    }

    // Scroll-triggered fade-in
    const observer = new IntersectionObserver((entries) => {
      entries.forEach(entry => {
        if (entry.isIntersecting) {
          entry.target.classList.add('visible');
        }
      });
    }, { threshold: 0.1, rootMargin: '0px 0px -40px 0px' });

    document.querySelectorAll('.fade-in').forEach(el => observer.observe(el));

    // Init Lucide icons
    document.addEventListener('DOMContentLoaded', () => {
      lucide.createIcons();
    });
  </script>
